browser_insert=r'''\nasync function parentEntryUiJourney(page,name){if(name!=='pc')return;await reset(page);const score=page.locator('#starterScore'),apply=page.locator('#starterScoreApply');await score.fill('440');await apply.click();let text=await page.locator('#starterScenarios').innerText();assert(/民办/.test(text)&&/中外/.test(text)&&/(新疆|西藏)/.test(text),'440 starter scenarios');await score.fill('580');await apply.click();text=await page.locator('#starterScenarios').innerText();assert(/211/.test(text),'580 starter 211');await score.fill('620');await apply.click();text=await page.locator('#starterScenarios').innerText();assert(/985/.test(text),'620 starter 985');await score.fill('650');await apply.click();text=await page.locator('#starterScenarios').innerText();assert(!/加预算|中外/.test(text),'650 starter must not nudge spending');}\nasync function schoolHistoryAliasJourney(page,name){if(name!=='pc')return;await reset(page);let data=await submitTurn(page,'580分，省内电气有哪些学校',{candidates:true});assert(data.result?.candidates?.ok===true,'580 electric candidate');data=await submitTurn(page,'沈阳工业大学自动化多少分',{history:true});assert(data.command.agentTask==='school_major_history','industrial automation task');assert(data.result.history.school==='沈阳工业大学','industrial school');assert(!bodySummary(data).includes('参考分数格式不正确'),'null score leaked into school history');data=await submitTurn(page,'沈阳工业大学所有专业的最低录取分',{history:true});assert(data.command.agentTask==='school_history','all-major history task');assert((data.result.history.records||[]).length>10,'all-major records unexpectedly tiny');assert(Number.isFinite(Number(data.result.history.summary?.minScore)),'all-major min score missing');data=await submitTurn(page,'沈航的电气呢',{history:true});assert(data.result.history.school==='沈阳航空航天大学',`沈航 alias failed: ${bodySummary(data.result.history)}`);data=await submitTurn(page,'辽科大的电气呢',{history:true});assert(data.result.history.school==='辽宁科技大学',`辽科大 alias failed: ${bodySummary(data.result.history)}`);data=await submitTurn(page,'电气在辽宁哪些学校有背景证据',{background:true});assert(data.command.agentTask==='major_background','major background task');assert((data.result.background.items||[]).some(item=>Array.isArray(item.schools)&&item.schools.length),'background school objects missing');await page.locator('.background-schools').first().evaluate(el=>el.open=true);assert(await page.locator('.background-school-link').count()>0,'background school links missing');const href=await page.locator('.background-school-link').first().getAttribute('href');assert(href?.includes('/ln-rank/?mode=school-all&school='),`background link invalid ${href}`);data=await submitTurn(page,'辽科大',{history:true});assert(data.result.history.school==='辽宁科技大学','school continuation lost');assert(data.result.history.majorKeyword?.includes('电气'),'major focus lost after background');}\nasync function scoreBandParentJourneys(page,name){if(name!=='pc')return;const basePrompts=new Map([[350,'350分，先看还有哪些真实可达的本科机会'],[440,'440分，辽宁省内先看能上的学校'],[500,'500分，辽宁省内先看学校和专业怎么平衡'],[580,'580分，省内机械看看'],[620,'620分，学校平台和专业质量怎么平衡'],[630,'630分，全国电气看看'],[650,'650分，不只看学校层次，优先比较专业质量和培养路径']]);for(const [score,prompt] of basePrompts){await reset(page);const first=await submitTurn(page,prompt,{candidates:true});assert(Number(first.resolvedView?.score)===score,`${score}: score drift`);assert(first.result?.candidates?.ok===true,`${score}: candidate failed`);if(score===440){let q=await submitTurn(page,'民办也可以，看看能增加哪些选择',{candidates:true});assert(q.resolvedView?.bottomLineMode==='all','440 private broaden');q=await submitTurn(page,'中外合作也可以，预算可以上浮',{candidates:true});assert(q.resolvedView?.bottomLineMode==='public_include_sino','440 sino');q=await submitTurn(page,'新疆、西藏也可以，优先公办',{candidates:true});assert(q.resolvedView?.regionKeys?.includes('province:新疆')&&q.resolvedView?.regionKeys?.includes('province:西藏'),'440 far-region');}if(score===580){const q=await submitTurn(page,'愿意加预算，看看有没有211中外或高收费项目值得研究',{candidates:true});assert(q.command.platformTarget==='211','580 platform target');assert(q.result.candidates?.platformUpgrade?.target==='211','580 platform preview');assert(q.result.candidates.platformUpgrade.complete===false,'211 preview must not claim complete');}if(score===620){const q=await submitTurn(page,'愿意加预算，看看有没有985中外或高收费项目值得研究',{candidates:true});assert(q.command.platformTarget==='985','620 platform target');assert(q.result.candidates?.platformUpgrade?.target==='985','620 platform preview');assert(q.result.candidates.platformUpgrade.complete===false,'985 preview must not claim complete');}}}\n'''
